 public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
 "Mixed weighted polynomial substitution", H("Weighted Polynomial Substitution"), Blocks(
Paragraph(Text("Let R be any commutative semiring, sigma and tau arbitrary types in independent universes, and v:sigma->Nat and w:tau->Nat arbitrary weights. Put A=MvPolynomial(tau,R) and use a separate univariate cover variable t of weight one in Polynomial(A). There is no finiteness assumption on either variable type, no positive-weight assumption, and no domain or nontriviality assumption on R. Polynomial and monomial supports make every sum finite. Subtraction alone requires CommRing R.")),
Paragraph(Text("HasTotalWeight(w,P,N) means that for every r:Nat and d:tau ->_0 Nat, a nonzero scalar coefficient coeff_d(coeff_r(P)) implies weight_w(d)+r=N. It is a support conservation law, not only a degree estimate. In particular r>N forces coeff_r(P)=0. Zero polynomials have every total weight, and zero weights and an empty variable type are included.")),
Paragraph(Text("The proof uses Mathlib weighted homogeneous polynomials, finite monomial evaluation, and both coefficient-convolution formulas. If a product coefficient is nonzero, some pair of cover degrees and then some pair of coefficient monomials has nonzero product. Each factor coefficient is nonzero even over a semiring with zero divisors; applying the two support laws and adding their weights proves conservation. Induction extends this to powers, finite products and sums. The finite evaluation expansion then preserves the source monomial weight. This shared conservation argument is the substantive reusable inference; constant, cast, additive and signed-coefficient facts are consumed support. These are classical graded-polynomial arguments, not a claim of literature novelty or a solution of a named open problem.")),
Paragraph(Text("The live application is the original half-Fock translation in LatticeHalfFockChargedLZero. The natural weights are 2k+1 and a translated variable is a difference of two terms of that same mixed weight. Signed coefficient lowering gives N-r without truncated subtraction and is the bridge to the original creation index e+B(a,a)+r. No second natural-subtraction API or unused above-weight wrapper is retained.")),
Describe.Lean(DescribeId.Create("total-weight-definition"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/WeightedPolynomialSubstitution.HasTotalWeight"),
 H("Mixed coefficient and cover weight"), StatementSource.FromAuthor(Disp(Seq(Call("HasTotalWeight", F.Id("w"), F.Id("P"), F.Id("N")), Iff, Call("supportConservation", F.Id("w"), F.Id("P"), F.Id("N"))))),
 AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For w:tau->Nat, P:Polynomial(MvPolynomial(tau,R)) and N:Nat, the definition quantifies every r:Nat and d:tau ->_0 Nat. Nonzero coeff_d(coeff_r(P)) implies weight_w(d)+r=N. Definitions carry no new-content credit."))), DescribeRole.Definition),
Describe.Lean(DescribeId.Create("total-weight-constant"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/WeightedPolynomialSubstitution.C"),
 H("Constant cover embedding"), StatementSource.FromAuthor(Disp(Seq(Call("Hom", F.Id("w"), F.Id("p"), F.Id("N")), Implies, Call("HasTotalWeight", F.Id("w"), Call("C", F.Id("p")), F.Id("N"))))),
 AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original R,tau,CommSemiring R,w,p,N and hp:IsWeightedHomogeneous w p N, Polynomial.C p has total weight N. Only cover degree zero survives; its coefficient homogeneity is exactly hp. This support lemma is used by the unit and evaluation proofs and by the original translation."))), DescribeRole.Theorem),
Describe.Lean(DescribeId.Create("total-weight-cover-power"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/WeightedPolynomialSubstitution.X_pow"),
 H("Pure cover powers"), StatementSource.FromAuthor(Disp(Call("HasTotalWeight", F.Id("w"), Seq(F.Id("t"), Caret, Grp(F.Id("k"))), F.Id("k")))),
 AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For arbitrary R,tau,CommSemiring R,w and k:Nat, X^k:Polynomial(MvPolynomial(tau,R)) has total weight k. Its only possible cover coefficient is the coefficient-ring unit at degree k, of coefficient weight zero. Used by the actual translated variable."))), DescribeRole.Theorem),
Describe.Lean(DescribeId.Create("total-weight-product"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/WeightedPolynomialSubstitution.mul"),
 H("Conservation through two coefficient convolutions"), StatementSource.FromAuthor(Disp(Seq(Call("HasTotalWeight", F.Id("w"), F.Id("P"), F.Id("N")), Land, Call("HasTotalWeight", F.Id("w"), F.Id("Q"), F.Id("M")), Implies, Call("HasTotalWeight", F.Id("w"), Seq(F.Id("P"), F.Id("Q")), Seq(F.Id("N"), Plus, F.Id("M")))))),
 AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For all original R,tau,CommSemiring R,w,P,Q,N,M and hP,hQ of the indicated total weights, P*Q has weight N+M. The two nonzero summands extracted from cover and coefficient antidiagonals give i+j=r and u+v=d. Additivity of Finsupp.weight gives weight(d)+r=N+M. No cancellation, integral-domain or positivity hypothesis is used. Powers, products, evaluation and translation consume this conservation."))), DescribeRole.Theorem),
Describe.Lean(DescribeId.Create("total-weight-difference"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/WeightedPolynomialSubstitution.sub"),
 H("Difference at a common weight"), StatementSource.FromAuthor(Disp(Seq(Call("HasTotalWeight", F.Id("w"), F.Id("P"), F.Id("N")), Land, Call("HasTotalWeight", F.Id("w"), F.Id("Q"), F.Id("N")), Implies, Call("HasTotalWeight", F.Id("w"), Seq(F.Id("P"), Minus, F.Id("Q")), F.Id("N"))))),
 AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Here R is a commutative ring. For w,P,Q,N and both original total-weight premises, P-Q has total weight N. Negation preserves scalar support and addition uses whichever summand coefficient is nonzero. This is support for the original difference defining halfTranslationVariable, not independent new mathematical content."))), DescribeRole.Theorem),
Describe.Lean(DescribeId.Create("weight-int-cast"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/WeightedPolynomialSubstitution.weight_intCast"),
 H("Exact natural to integer weight conversion"), StatementSource.FromAuthor(Disp(Seq(Call("weight", F.Id("wZ"), F.Id("d")), Eq, Call("IntCast", Call("weight", F.Id("w"), F.Id("d")))))),
 AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For any tau, w:tau->Nat and d:tau ->_0 Nat, Finsupp.weight (fun x => (w x:Int)) d equals the integer cast of Finsupp.weight w d. Expand the same finite support sum and commute casts with sums and products. This normalization is consumed by signed lowering and half-frequency energy conversion; it supplies no separate content credit."))), DescribeRole.Theorem),
