 AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original R,tau,CommSemiring R,w,p,N and hp:IsWeightedHomogeneous w p N, p is homogeneous for integer-cast weights at (N:Int). Apply weight_intCast to each nonzero coefficient. The creation and oscillator-input stages consume it."))), DescribeRole.Theorem),
Describe.Lean(DescribeId.Create("coefficient-signed-lowering"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/WeightedPolynomialSubstitution.coeff_homogeneous_int"),
 H("Signed coefficient lowering"), StatementSource.FromAuthor(Disp(Seq(Call("HasTotalWeight", F.Id("w"), F.Id("P"), F.Id("N")), Implies, Call("Hom", F.Id("wZ"), Call("coeff", F.Id("r"), F.Id("P")), Seq(Call("IntCast", F.Id("N")), Minus, F.Id("r")))))),
 AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For all original R,tau,CommSemiring R,w,P,N,hP and r:Nat, P.coeff r is integer-weight homogeneous at (N:Int)-r. Cast the exact equality weight(d)+r=N and subtract in Int. In particular r>N does not turn a negative weight into zero: no coefficient monomial has negative natural weight, so the coefficient vanishes. This is the live signed lowering used by the original charged proof."))), DescribeRole.Theorem),
Describe.Lean(DescribeId.Create("weighted-substitution-total-weight"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/WeightedPolynomialSubstitution.eval2_totalWeight"),
 H("Generic weighted substitution conservation"), StatementSource.FromAuthor(Disp(Seq(Open, Forall, Sp, F.Id("i"), Comma, Sp, Call("HasTotalWeight", F.Id("w"), Call("f", F.Id("i")), Call("v", F.Id("i"))), Close, Land, Call("Hom", F.Id("v"), F.Id("p"), F.Id("N")), Implies, Call("HasTotalWeight", F.Id("w"), Call("eval2", F.Id("f"), F.Id("p")), F.Id("N"))))),
 AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For independent arbitrary types sigma,tau,R, CommSemiring R, v:sigma->Nat, w:tau->Nat, f:sigma->Polynomial(MvPolynomial(tau,R)), hf:forall i, HasTotalWeight w (f i) (v i), p:MvPolynomial(sigma,R), N:Nat and hp:IsWeightedHomogeneous v p N, the original MvPolynomial.eval2 (algebraMap R (Polynomial(MvPolynomial(tau,R)))) f p has total weight N. Expand p over finite monomial support. Each evaluated variable power has its prescribed multiple weight; their product has the source monomial weight N. The scalar coefficient embeds at weight zero and the finite sum keeps N. The actual halfTranslatedPolynomial proof consumes the theorem."))), DescribeRole.Theorem))));
